(* Mash tun temperature PID control via steam valve *)
VAR
    temp, setpoint, error, valve : REAL;
END_VAR

temp := Read('Brewery.Mashing.MashTunTemp');
setpoint := Read('Brewery.Mashing.MashTunTempSetpoint');
error := setpoint - temp;
valve := Read('Brewery.Mashing.SteamValve_Pct') + error * 2.0;
IF valve > 100.0 THEN valve := 100.0; END_IF;
IF valve < 0.0 THEN valve := 0.0; END_IF;
Write('Brewery.Mashing.SteamValve_Pct', valve);
